export async function main(argv,dependencies={}){const options=parseArgs(argv);return options.help?{help:HELP}:runVerification(options,dependencies);}
if(process.argv[1]&&pathToFileURL(resolve(process.argv[1])).href===import.meta.url){try{const result=await main(process.argv.slice(2));if(result.help)console.log(result.help);else{console.log(JSON.stringify(result,null,2));if(!result.ok)process.exitCode=1;}}catch(error){console.error(JSON.stringify(safeReport({ok:false,stage:error instanceof QuestionUatFailure?error.stage:'arguments'})));process.exitCode=1;}}
